import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {constrainTarget,terrainHeight,isTap,LAKE,WORLD,LANDMARKS} from './world.js';

export function createNavigation(THREE,camera,canvas,container,onTap,onExplore){
 const controls=new OrbitControls(camera,canvas);controls.enableDamping=true;controls.dampingFactor=.12;controls.screenSpacePanning=false;controls.minDistance=3;controls.maxDistance=WORLD.maxViewDistance;controls.minPolarAngle=.12;controls.maxPolarAngle=Math.PI/2-.035;controls.panSpeed=1;controls.rotateSpeed=.55;
 const keys=new Set(),pointers=new Map(),forward=new THREE.Vector3(),right=new THREE.Vector3();let returnTrip=null;
 const editable=target=>target.closest('input,select,button,dialog,textarea');
 function clearInput(){keys.clear();pointers.clear();}
 addEventListener('blur',clearInput);document.addEventListener('visibilitychange',()=>{if(document.hidden)clearInput();});
 addEventListener('keydown',event=>{if(editable(event.target)||event.ctrlKey||event.metaKey||event.altKey)return;if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','ShiftLeft','ShiftRight'].includes(event.code)){event.preventDefault();keys.add(event.code);returnTrip=null;onExplore();}});
 addEventListener('keyup',event=>keys.delete(event.code));
 controls.addEventListener('start',()=>{returnTrip=null;});
 container.addEventListener('pointerdown',event=>{container.focus({preventScroll:true});returnTrip=null;const start={x:event.clientX,y:event.clientY,time:performance.now(),button:event.button,multitouch:pointers.size>0,dragged:false};if(pointers.size)for(const p of pointers.values())p.multitouch=true;pointers.set(event.pointerId,start);},true);
 container.addEventListener('pointermove',event=>{const p=pointers.get(event.pointerId);if(p&&Math.hypot(event.clientX-p.x,event.clientY-p.y)>6){p.dragged=true;onExplore();}},true);
 container.addEventListener('pointerup',event=>{const start=pointers.get(event.pointerId);pointers.delete(event.pointerId);if(start&&isTap(start,{x:event.clientX,y:event.clientY,time:performance.now()}))onTap(event.clientX,event.clientY);},true);
 for(const type of ['pointercancel','lostpointercapture'])container.addEventListener(type,event=>pointers.delete(event.pointerId));
 container.addEventListener('wheel',()=>{returnTrip=null;onExplore();},{passive:true});
 function home(instant=false){clearInput();controls.enabled=true;controls.enableDamping=false;controls.update();controls.enableDamping=true;const mobile=container.clientWidth<600;const position=new THREE.Vector3(mobile?16:45,mobile?105:68,mobile?138:100),target=new THREE.Vector3(0,.8,0);if(instant||matchMedia('(prefers-reduced-motion: reduce)').matches){returnTrip=null;controls.reset();controls.target.copy(target);camera.position.copy(position);controls.update();}else{returnTrip={position,target,from:camera.position.clone(),fromTarget:controls.target.clone(),elapsed:0};} }
 function update(delta){
  if(returnTrip){returnTrip.elapsed+=delta;const t=Math.min(1,returnTrip.elapsed/1.35),s=t*t*(3-2*t);camera.position.lerpVectors(returnTrip.from,returnTrip.position,s);controls.target.lerpVectors(returnTrip.fromTarget,returnTrip.target,s);camera.position.y=Math.max(camera.position.y,terrainHeight(camera.position.x,camera.position.z)+2);camera.lookAt(controls.target);if(t===1){returnTrip=null;controls.update();}return;}
  let longitudinal=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0),lateral=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0);
  if(longitudinal||lateral){forward.subVectors(controls.target,camera.position);forward.y=0;forward.normalize();right.crossVectors(forward,camera.up).normalize();const scale=delta*(keys.has('ShiftLeft')||keys.has('ShiftRight')?60:16)/Math.hypot(longitudinal,lateral);forward.multiplyScalar(longitudinal*scale).addScaledVector(right,lateral*scale);camera.position.add(forward);controls.target.add(forward);}
  controls.update();const fixed=constrainTarget(controls.target.x,controls.target.z);const dx=fixed.x-controls.target.x,dz=fixed.z-controls.target.z,dy=fixed.y-controls.target.y;controls.target.set(fixed.x,fixed.y,fixed.z);camera.position.x+=dx;camera.position.z+=dz;camera.position.y+=dy;camera.position.y=Math.max(camera.position.y,terrainHeight(camera.position.x,camera.position.z)+1.8);camera.lookAt(controls.target);
 }
 function hold(code,pressed){if(pressed){keys.add(code);returnTrip=null;onExplore();}else keys.delete(code);}
 home(true);controls.saveState();
 const map=document.getElementById('map'),ctx=map.getContext('2d');let mapClock=0;
 function drawMap(delta){mapClock+=delta;if(mapClock<.12)return;mapClock=0;const size=136,scale=55/(WORLD.travelRadius+WORLD.maxViewDistance);ctx.clearRect(0,0,size,size);ctx.fillStyle='#c6d5a70b';ctx.strokeStyle='#c6d5a72d';ctx.beginPath();ctx.arc(68,68,58,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#a4c7af';ctx.beginPath();ctx.ellipse(68,68,LAKE.x*scale,LAKE.z*scale,0,0,Math.PI*2);ctx.fill();for(const place of LANDMARKS){ctx.fillStyle=place.color;ctx.beginPath();ctx.arc(68+place.x*scale,68+place.z*scale,2,0,Math.PI*2);ctx.fill();}ctx.strokeStyle='#e4d7a455';ctx.setLineDash([2,4]);ctx.beginPath();ctx.moveTo(68,68);ctx.lineTo(68+camera.position.x*scale,68+camera.position.z*scale);ctx.stroke();ctx.setLineDash([]);const x=68+camera.position.x*scale,z=68+camera.position.z*scale;ctx.save();ctx.translate(x,z);ctx.rotate(Math.atan2(controls.target.z-camera.position.z,controls.target.x-camera.position.x));ctx.fillStyle='#f5e6b8';ctx.beginPath();ctx.moveTo(6,0);ctx.lineTo(-4,-3);ctx.lineTo(-2,0);ctx.lineTo(-4,3);ctx.closePath();ctx.fill();ctx.restore();const nearby=LANDMARKS.find(place=>Math.hypot(camera.position.x-place.x,camera.position.z-place.z)<55);document.getElementById('place').textContent=nearby?nearby.name:Math.hypot(camera.position.x,camera.position.z)<120?'Clareira central':'Caminhos do bosque';document.getElementById('distance').textContent=`${Math.round(Math.max(0,Math.hypot(camera.position.x,camera.position.z)-LAKE.x))} m da clareira`;}
 return {update,home,hold,drawMap,clearInput,controls};
}
